// vendored from @patternmode/swatch@5.1.3 — generated by scripts/build-registry.mjs; do not hand-edit.
import { deriveDistribution, joinClassNames } from "@/lib/patternmode/system";
import type { HTMLAttributes } from "react";
import type { DistributionSegment } from "../Distribution/distribution-math";
import {
  DistributionSegmentLegend,
  DistributionSegments,
} from "../Distribution/distribution-parts";

export interface DistributionDisplayProps extends Omit<
  HTMLAttributes<HTMLElement>,
  "role" | "onSelect"
> {
  /** Label used in summary legends for assigned segment weight. */
  assignedLabel?: string;
  /** Label used when `emptyValue` contributes unassigned weight. */
  emptyLabel?: string;
  /**
   * Extra unassigned weight included in derived percentage calculations.
   *
   * Default `0`.
   */
  emptyValue?: number;
  /**
   * Legend style for the read-only display.
   *
   * Default `"segments"`.
   */
  legend?: "segments" | "summary" | false;
  /**
   * When provided, each segment renders as a button and selecting one
   * invokes this callback. Pair with `selectedSegmentId` to mark a segment
   * as selected (renders a ring). Read-only by default.
   */
  onSegmentSelect?: (segment: DistributionSegment) => void;
  segments: DistributionSegment[];
  /** Id of the selected segment — renders a ring on that segment. */
  selectedSegmentId?: string;
}

interface DistributionSummaryLegendProps {
  assignedLabel: string;
  emptyLabel: string;
  emptyPercentage: number;
  emptyValue: number;
}

/**
 * Segment shares and the unassigned remainder's share, from one derivation
 * over the segment weights followed by `emptyValue`, so the remainder counts
 * toward the total.
 */
const getDistributionDisplayShares = (segments: DistributionSegment[], emptyValue: number) => {
  const { percentages } = deriveDistribution([
    ...segments.map((segment) => segment.value),
    emptyValue,
  ]);
  return {
    emptyPercentage: percentages[segments.length] ?? 0,
    percentages: percentages.slice(0, segments.length),
  };
};

const getDistributionDisplayAccessibleLabel = (
  segments: DistributionSegment[],
  percentages: number[],
  emptyValue: number,
  emptyLabel: string,
  emptyPercentage: number,
): string => {
  const segmentLabels = segments.map(
    (segment, index) => `${segment.label ?? segment.id} ${Math.round(percentages[index] ?? 0)}%`,
  );
  if (emptyValue > 0) {
    segmentLabels.push(`${emptyLabel} ${Math.round(emptyPercentage)}%`);
  }

  return segmentLabels.join(", ");
};

const DistributionSummaryLegend = ({
  assignedLabel,
  emptyLabel,
  emptyPercentage: unroundedEmptyPercentage,
  emptyValue,
}: DistributionSummaryLegendProps) => {
  const emptyPercentage = Math.round(unroundedEmptyPercentage);

  return (
    <div className="patternmode-distribution-bar__legend">
      <span>
        {Math.max(0, 100 - emptyPercentage)}% {assignedLabel}
      </span>
      {emptyValue > 0 ? (
        <span>
          {emptyPercentage}% {emptyLabel}
        </span>
      ) : null}
    </div>
  );
};

/**
 * A read-only proportional strip: one bordered track of contiguous weighted
 * segments, with an optional legend.
 *
 * **Not an editor.** `DistributionBar` is the editor — it renders `role="slider"`
 * handles and mutates its segments. This one draws them and nothing else, which
 * is the right shape when the weights were computed rather than allocated by a
 * human: dragging the edge of a bucket a computation filled just lies.
 *
 * It lives in its own directory for that reason. It used to be filed inside
 * `DistributionBar/` and exported from the editor's barrel, and the result was
 * that two separate consumers looked for a read-only distribution strip, did not
 * find one, and reported the territory unserved.
 *
 * Contiguity is the point: one track with hairline boundaries, not a flex row of
 * individually-rounded `Swatch` blocks, which leaks each swatch's own radius and
 * shadow as seams.
 *
 * Pass `onSegmentSelect` to make each segment a button — selection is still not
 * editing, so the element stays a `figure` unless it becomes interactive.
 */
export const DistributionDisplay = ({
  "aria-label": ariaLabel,
  assignedLabel = "assigned",
  className,
  emptyLabel = "unassigned",
  emptyValue = 0,
  legend = "segments",
  onSegmentSelect,
  segments,
  selectedSegmentId,
  ...props
}: DistributionDisplayProps) => {
  const { emptyPercentage, percentages } = getDistributionDisplayShares(segments, emptyValue);
  const interactive = Boolean(onSegmentSelect);
  const accessibleLabel =
    ariaLabel ??
    getDistributionDisplayAccessibleLabel(
      segments,
      percentages,
      emptyValue,
      emptyLabel,
      emptyPercentage,
    );

  const content = (
    <>
      <div className="patternmode-distribution-bar__track">
        <DistributionSegments
          emptyPercentage={emptyPercentage}
          emptyValue={emptyValue}
          onSegmentSelect={onSegmentSelect}
          percentages={percentages}
          segments={segments}
          selectedSegmentId={selectedSegmentId}
        />
      </div>
      {legend === "segments" ? (
        <DistributionSegmentLegend
          emptyLabel={emptyLabel}
          emptyPercentage={emptyPercentage}
          emptyValue={emptyValue}
          percentages={percentages}
          segments={segments}
        />
      ) : null}
      {legend === "summary" ? (
        <DistributionSummaryLegend
          assignedLabel={assignedLabel}
          emptyLabel={emptyLabel}
          emptyPercentage={emptyPercentage}
          emptyValue={emptyValue}
        />
      ) : null}
    </>
  );
  const sharedClassName = joinClassNames("patternmode-distribution-display", className);

  return interactive ? (
    <fieldset
      {...props}
      aria-label={accessibleLabel}
      className={sharedClassName}
      data-slot="distribution-display"
    >
      {content}
    </fieldset>
  ) : (
    <figure
      {...props}
      aria-label={accessibleLabel}
      className={sharedClassName}
      data-slot="distribution-display"
    >
      {content}
    </figure>
  );
};
